// w7003-parse-payload
// Slice the 61-byte fixed-width callback_data: T(12)A(1)N(8)S(8)H(32).
// Anchor MUST match every mint node (see w2012a, w2w03d, fixture).
// NOTE: must read from the trigger, not $input — w7002 (answerQuery) replaces
// the item's json with the Telegram API response, losing the callback_query.
const ANCHOR_UNIX = 1767225600; // 2026-01-01T00:00:00Z

const raw = $('w7001-telegram-trigger').item.json;
const cq = raw.callback_query || {};
const cb = (cq.data || '').toString();

if (cb.length !== 61) {
  return { json: {
    _abort: true,
    _abort_reason: 'callback_data length mismatch: expected 61, got ' + cb.length,
    callback_query_id: cq.id || null,
    chat_id: (cq.message && cq.message.chat && cq.message.chat.id) || null,
    message_id: (cq.message && cq.message.message_id) || null,
    from_user_id: (cq.from && cq.from.id) || null,
    raw_callback_data: cb
  }};
}

const token = cb.slice(0, 12);
const action = cb.slice(12, 13);
const nonce = cb.slice(13, 21);
const ts_hex = cb.slice(21, 29);
const hmac_hex = cb.slice(29, 61);

const ts_minutes = parseInt(ts_hex, 16);
const ts_unix_seconds = ANCHOR_UNIX + (ts_minutes * 60);

return { json: {
  token,
  action,
  nonce,
  ts_hex,
  hmac_hex,
  ts_unix_seconds,
  callback_query_id: cq.id || null,
  chat_id: (cq.message && cq.message.chat && cq.message.chat.id) || null,
  message_id: (cq.message && cq.message.message_id) || null,
  from_user_id: (cq.from && cq.from.id) || null,
  message_text: (cq.message && cq.message.text) || null,
  raw_callback_data: cb
}};

// w7004-hmac-validate
// Verify HMAC-SHA256(token+action+nonce+ts_hex) truncated to 16 bytes hex (32 chars).
// Replay window: -60s (clock skew) to +600s (10 minutes).
const crypto = require('crypto');

const data = $input.item.json;

if (data._abort) {
  return { json: { ...data, validated: false, reject_reason: data._abort_reason } };
}

const secret = $env.TELEGRAM_CALLBACK_SECRET;
if (!secret || secret.length < 32) {
  return { json: { ...data, validated: false, reject_reason: 'TELEGRAM_CALLBACK_SECRET missing or too short' } };
}

const payload = data.token + data.action + data.nonce + data.ts_hex;
const expected = crypto.createHmac('sha256', secret).update(payload).digest('hex').slice(0, 32);

let hmac_ok = false;
try {
  hmac_ok = crypto.timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(data.hmac_hex, 'hex'));
} catch (e) {
  return { json: { ...data, validated: false, reject_reason: 'hmac comparison threw: ' + e.message } };
}

if (!hmac_ok) {
  return { json: { ...data, validated: false, reject_reason: 'hmac mismatch' } };
}

const now_seconds = Math.floor(Date.now() / 1000);
const age = now_seconds - data.ts_unix_seconds;
if (age > 600) {
  return { json: { ...data, validated: false, reject_reason: 'callback older than 10 min (age=' + age + 's)' } };
}
if (age < -60) {
  return { json: { ...data, validated: false, reject_reason: 'callback timestamp in future (age=' + age + 's)' } };
}

return { json: { ...data, validated: true, callback_age_seconds: age } };

// w7006-lookup-pending
// Read /miru-data/pending_callbacks.jsonl (append-only). Walk in reverse to find
// the latest 'intent' row matching token, AND any 'decided' row for same token.
const fs = require('fs');
const PENDING = '/miru-data/pending_callbacks.jsonl';

const data = $input.item.json;
const targetToken = data.token;

let content = '';
try {
  if (fs.existsSync(PENDING)) {
    content = fs.readFileSync(PENDING, 'utf8');
  }
} catch (e) {
  return { json: { ...data, found: false, reject_reason: 'pending_callbacks read error: ' + e.message } };
}

const lines = content.split('\n').filter(Boolean);
let intentRow = null;
let decidedRow = null;
for (let i = lines.length - 1; i >= 0; i--) {
  let row;
  try { row = JSON.parse(lines[i]); } catch (e) { continue; }
  if (row.token !== targetToken) continue;
  if (row.kind === 'decided' && !decidedRow) decidedRow = row;
  if (row.kind === 'intent' && !intentRow) intentRow = row;
  if (intentRow && decidedRow) break;
}

if (!intentRow) {
  return { json: { ...data, found: false, reject_reason: 'token not found in pending_callbacks' } };
}

if (decidedRow) {
  return { json: { ...data, found: true, already_decided: true, decided_action: decidedRow.action, decided_at: decidedRow.decided_at, intent_row: intentRow } };
}

return { json: {
  ...data,
  found: true,
  already_decided: false,
  trace_id: intentRow.trace_id,
  issue_id: intentRow.issue_id,
  issue_identifier: intentRow.issue_identifier,
  chosen_worker: intentRow.chosen_worker,
  confidence: intentRow.confidence,
  risk: intentRow.risk,
  button_set: intentRow.button_set,
  issue_existing_label_ids: intentRow.issue_existing_label_ids || [],
  labels_map: intentRow.labels_map || {},
  intent_written_at: intentRow.intent_written_at
}};

// w7-mcp-read-pending (PRO-122)
const fs = require('fs');
const MCP = '/miru-data/mcp_gateway_pending_writes.jsonl';
const data = $input.item.json;
const traceId = data.trace_id;
if (!traceId) {
  return { json: { ...data, _mcp_error: 'missing trace_id' } };
}
let content = '';
try {
  if (fs.existsSync(MCP)) content = fs.readFileSync(MCP, 'utf8');
} catch (e) {
  return { json: { ...data, _mcp_error: 'read mcp_gateway_pending_writes: ' + e.message } };
}
const lines = content.split(String.fromCharCode(10)).filter(Boolean);
let row = null;
for (let i = lines.length - 1; i >= 0; i--) {
  let r;
  try { r = JSON.parse(lines[i]); } catch (e2) { continue; }
  if (r.kind === 'intent' && r.request_id === traceId) {
    row = r;
    break;
  }
}
if (!row) {
  return { json: { ...data, _mcp_error: 'no matching intent row for request_id', _mcp_trace: traceId } };
}
const op = row.operation;
let base = String($env.N8N_INTERNAL_API_BASE || 'http://127.0.0.1:5678');
while (base.endsWith('/')) base = base.slice(0, -1);
const apiKey = $env.N8N_API_KEY;
if (!apiKey) {
  return { json: { ...data, _mcp_error: 'N8N_API_KEY not set on n8n container' } };
}
let n8n_method;
let n8n_url;
if (op === 'create_workflow') {
  n8n_method = 'POST';
  n8n_url = base + '/api/v1/workflows';
} else if (op === 'update_workflow') {
  const wid = row.workflow_id;
  if (!wid) {
    return { json: { ...data, _mcp_error: 'update_workflow missing workflow_id' } };
  }
  n8n_method = 'PUT';
  n8n_url = base + '/api/v1/workflows/' + wid;
} else {
  return { json: { ...data, _mcp_error: 'unknown operation: ' + op } };
}
const bodyObj = row.workflow_json;
if (!bodyObj || typeof bodyObj !== 'object') {
  return { json: { ...data, _mcp_error: 'workflow_json missing or invalid' } };
}
const decided_at = new Date().toISOString();
return { json: {
  ...data,
  _mcp_pending_row: row,
  n8n_method,
  n8n_url,
  mcp_mutation_body: bodyObj,
  decided_at,
  action_label: 'Approve (MCP n8n write)'
}};

// w7-mcp-mark-decided-approved (PRO-122)
const fs = require('fs');
const PENDING = '/miru-data/pending_callbacks.jsonl';
const prior = $('w7-mcp-read-pending').item.json;
const httpOut = $input.item.json;
const decided_at = prior.decided_at || new Date().toISOString();
let applyOk = true;
let applyErr = null;
if (httpOut && httpOut.error) {
  applyOk = false;
  applyErr = (httpOut.error.message && String(httpOut.error.message)) || JSON.stringify(httpOut.error);
} else if (httpOut && httpOut.message && String(httpOut.message).toLowerCase().indexOf('error') >= 0) {
  applyOk = false;
  applyErr = String(httpOut.message);
}
const sc = httpOut.statusCode != null ? httpOut.statusCode : httpOut.status;
if (sc != null && (sc < 200 || sc >= 300)) {
  applyOk = false;
  applyErr = applyErr || ('HTTP ' + sc);
}
const decidedRow = {
  kind: 'decided',
  token: prior.token,
  action: prior.action,
  action_label: prior.action_label || 'Approve (MCP n8n write)',
  decided_at,
  decided_by_user_id: prior.from_user_id != null ? prior.from_user_id : null,
  trace_id: prior.trace_id,
  task_id: prior.issue_id || null,
  task_identifier: prior.issue_identifier || null,
  edit_message_ok: applyOk,
  mcp_n8n_write_outcome: applyOk ? 'applied' : 'n8n_http_failed',
  mcp_n8n_write_error: applyErr
};
fs.appendFileSync(PENDING, JSON.stringify(decidedRow) + String.fromCharCode(10));
return { json: { ...prior, _mcp_apply_ok: applyOk, _mcp_apply_err: applyErr } };

// w7-mcp-triage-mark (PRO-122)
const fs = require('fs');
const PENDING = '/miru-data/pending_callbacks.jsonl';
const d = $input.item.json;
const decided_at = new Date().toISOString();
const action_label = 'Triage (declined MCP n8n write)';
const decidedRow = {
  kind: 'decided',
  token: d.token,
  action: d.action,
  action_label,
  decided_at,
  decided_by_user_id: d.from_user_id != null ? d.from_user_id : null,
  trace_id: d.trace_id,
  task_id: d.issue_id || null,
  task_identifier: d.issue_identifier || null,
  edit_message_ok: true,
  mcp_n8n_write_outcome: 'declined_triage'
};
fs.appendFileSync(PENDING, JSON.stringify(decidedRow) + String.fromCharCode(10));
return { json: { ...d, decided_at, action_label } };

// w7008-build-mutation
// Branch on action -> compute next label_ids + Linear GraphQL mutation body.
// Reached only for original-message actions {a, t, r} via w7-action-router-1.
// 'o' (Override) is now routed to w7-mint-picker-keyboard instead — its branch
// here is retained as a defensive fallback only.
const data = $input.item.json;
const labelsMap = data.labels_map || {};
const existingIds = (data.issue_existing_label_ids || []).slice();
const chosenWorker = data.chosen_worker;

const pendingApprovalId = labelsMap['pending-approval'];
const triageId = labelsMap['triage'];
const manualInterventionId = labelsMap['manual-intervention-required'];
const chosenWorkerId = labelsMap[chosenWorker];

const actionLabelMap = { a: 'Approve', o: 'Override', t: 'Triage', r: 'Request Revision' };
const actionLabel = actionLabelMap[data.action] || ('Unknown(' + data.action + ')');

if (!pendingApprovalId) {
  return { json: { ...data, _build_error: 'pending-approval label id missing from labels_map' } };
}

let nextIds = existingIds.filter(id => id !== pendingApprovalId);

if (data.action === 'a') {
  // Approve: ensure worker label is present (PRO-157), drop pending-approval (already filtered).
  if (!chosenWorkerId) {
    return { json: { ...data, _build_error: 'worker label id for "' + chosenWorker + '" missing from labels_map' } };
  }
  if (!nextIds.includes(chosenWorkerId)) {
    nextIds.push(chosenWorkerId);
  }
} else if (data.action === 'o') {
  // Defensive fallback: Override should now route to picker-mint.
  if (chosenWorkerId) nextIds = nextIds.filter(id => id !== chosenWorkerId);
  if (triageId && !nextIds.includes(triageId)) nextIds.push(triageId);
} else if (data.action === 't') {
  // Triage: add triage label
  if (triageId && !nextIds.includes(triageId)) nextIds.push(triageId);
} else if (data.action === 'r') {
  // Request Revision: add manual-intervention-required
  if (manualInterventionId && !nextIds.includes(manualInterventionId)) nextIds.push(manualInterventionId);
} else {
  return { json: { ...data, _build_error: 'unknown action code: ' + data.action } };
}

const decided_at = new Date().toISOString();
const commentBody = '**W7 callback decided: ' + actionLabel + '**\n\n'
  + 'Tap source: Telegram inline button\n'
  + 'Decided at: ' + decided_at + '\n'
  + 'Decided by user_id: ' + (data.from_user_id != null ? data.from_user_id : 'unknown') + '\n'
  + 'Original proposal: ' + chosenWorker + ' (conf ' + (data.confidence != null ? data.confidence : 'n/a') + ', risk ' + (data.risk || 'n/a') + ')\n'
  + 'Callback age at decision: ' + (data.callback_age_seconds != null ? data.callback_age_seconds + 's' : 'unknown') + '\n\n'
  + 'trace_id: ' + (data.trace_id || 'unknown');

const mutation_body_obj = {
  query: 'mutation W7Apply($issueId: String!, $labelIds: [String!]!, $commentBody: String!) { issueUpdate(id: $issueId, input: { labelIds: $labelIds }) { success issue { identifier } } commentCreate(input: { issueId: $issueId, body: $commentBody }) { success comment { id } } }',
  variables: { issueId: data.issue_id, labelIds: nextIds, commentBody }
};

return { json: { ...data, action_label: actionLabel, decided_at, next_label_ids: nextIds, mutation_body_obj } };

// w7011-mark-decided
// Two file appends: pending_callbacks.jsonl 'decided' row + routing_history.jsonl extension row.
const fs = require('fs');
const PENDING = '/miru-data/pending_callbacks.jsonl';
const HISTORY = '/miru-data/routing_history.jsonl';
const WORKFLOW_VERSION = 'phase-2-v1';

const prior = $('w7008-build-mutation').item.json;
const editResp = $input.item.json;

const decided_at = prior.decided_at;
const action = prior.action;
const action_label = prior.action_label;
const token = prior.token;
const trace_id = prior.trace_id;
const task_id = prior.issue_id;
const task_identifier = prior.issue_identifier;

// 1) pending_callbacks.jsonl: 'decided' row
const decidedRow = {
  kind: 'decided',
  token,
  action,
  action_label,
  decided_at,
  decided_by_user_id: prior.from_user_id != null ? prior.from_user_id : null,
  trace_id,
  task_id,
  task_identifier,
  edit_message_ok: !(editResp && editResp.error)
};
fs.appendFileSync(PENDING, JSON.stringify(decidedRow) + '\n');

// 2) routing_history.jsonl: full row matching canon schema + Phase 2 extensions
const historyRow = {
  timestamp: decided_at,
  trace_id,
  task_id,
  task_identifier,
  extracted_signals: null,
  ranked_candidates: null,
  chosen_worker: prior.chosen_worker,
  confidence: prior.confidence,
  risk: prior.risk,
  operator_override_flag: action !== 'a',
  outcome: 'callback-decided',
  worker_response_ref: 'callback-' + token,
  proposed_model_version: null,
  actual_model_version: null,
  w2_workflow_version: WORKFLOW_VERSION,
  callback_source: 'telegram',
  button_tapped: action_label,
  button_set: prior.button_set,
  callback_age_seconds: prior.callback_age_seconds != null ? prior.callback_age_seconds : null,
  decided_at,
  decided_by_user_id: prior.from_user_id != null ? prior.from_user_id : null
};
fs.appendFileSync(HISTORY, JSON.stringify(historyRow) + '\n');

return { json: { ...prior, _decided_persisted: true, _history_persisted: true } };

// w7-mint-picker-keyboard (PRO-80 Phase A)
// Override tap arrives here. Re-mint a 6-button picker keyboard re-using the
// existing token (HMAC anchor + pattern shared with w2012a-mint-callback-token).
// No pending_callbacks row written — the original 'intent' row remains valid;
// the picker tap eventually writes the 'decided' row.
const crypto = require('crypto');
const ANCHOR_UNIX = 1767225600;

const data = $input.item.json;
const secret = $env.TELEGRAM_CALLBACK_SECRET;
if (!secret) throw new Error('TELEGRAM_CALLBACK_SECRET not set');

const token = data.token;
const ts_minutes = Math.floor((Math.floor(Date.now()/1000) - ANCHOR_UNIX) / 60);
const ts_hex = ts_minutes.toString(16).padStart(8, '0').slice(-8);

function pickerButton(actionCode, label) {
  const nonce = crypto.randomBytes(4).toString('hex');
  const payload = token + actionCode + nonce + ts_hex;
  const hmac = crypto.createHmac('sha256', secret).update(payload).digest('hex').slice(0, 32);
  const cb = token + actionCode + nonce + ts_hex + hmac;
  if (cb.length !== 61) throw new Error('picker callback_data length mismatch: ' + cb.length);
  return { text: label, callback_data: cb };
}

const inline_keyboard = [
  [pickerButton('c', 'Claude Code'), pickerButton('u', 'Cursor'), pickerButton('x', 'Codex')],
  [pickerButton('g', 'Gemini CLI'), pickerButton('T', 'Triage'), pickerButton('b', '\u21A9 Back')]
];

const telegram_edit_body = {
  chat_id: data.chat_id,
  message_id: data.message_id,
  reply_markup: { inline_keyboard }
};

return { json: { ...data, telegram_edit_body, _picker_minted_at: new Date().toISOString() } };

// w7-picker-build-mutation (PRO-80 Phase A)
// Picker button tap (c/u/x/g/T) — compute next label_ids and Linear mutation
// for the operator-selected worker (or triage). Maps action codes to canonical
// Linear label names; gemini is operator-locked decision (PRO-80 prompt).
const data = $input.item.json;

const ACTION_TO_LABEL = {
  c: 'claude-code',
  u: 'cursor',
  x: 'codex',
  g: 'gemini',
  T: 'triage'
};
const ACTION_TO_DISPLAY = {
  c: 'Claude Code',
  u: 'Cursor',
  x: 'Codex',
  g: 'Gemini CLI',
  T: 'Triage'
};

const labelName = ACTION_TO_LABEL[data.action];
const display = ACTION_TO_DISPLAY[data.action];

if (!labelName) {
  return { json: { ...data, _build_error: 'unknown picker action: ' + data.action } };
}

const labelsMap = data.labels_map || {};
const selectedId = labelsMap[labelName];
const pendingApprovalId = labelsMap['pending-approval'];
const chosenWorkerId = labelsMap[data.chosen_worker];
// Worker keys for label cleanup. 'gemini' (not 'gemini-cli') is canonical
// per PRO-87 audit decision (operator ruling 2026-04-25).
const KNOWN_WORKER_KEYS = ['claude-code', 'cursor', 'codex', 'gemini'];

if (!selectedId) {
  return { json: { ...data, _build_error: 'picker label not in labels_map: ' + labelName + ' (ensure label exists in Linear so w2006 picks it up)' } };
}
if (!pendingApprovalId) {
  return { json: { ...data, _build_error: 'pending-approval label id missing from labels_map' } };
}

// Drop pending-approval, drop any prior worker label, add the selected label.
let nextIds = (data.issue_existing_label_ids || []).slice();
nextIds = nextIds.filter(id => id !== pendingApprovalId);
for (const k of KNOWN_WORKER_KEYS) {
  const wid = labelsMap[k];
  if (wid) nextIds = nextIds.filter(id => id !== wid);
}
if (chosenWorkerId) nextIds = nextIds.filter(id => id !== chosenWorkerId);
if (!nextIds.includes(selectedId)) nextIds.push(selectedId);

const overrideFlag = labelName !== data.chosen_worker;
const decided_at = new Date().toISOString();
const commentBody = '**W7 picker decided: ' + display + '**\n\n'
  + 'Picker selection via Telegram inline button\n'
  + 'Decided at: ' + decided_at + '\n'
  + 'Decided by user_id: ' + (data.from_user_id != null ? data.from_user_id : 'unknown') + '\n'
  + 'W2 proposal: ' + data.chosen_worker + ' (conf ' + (data.confidence != null ? data.confidence : 'n/a') + ', risk ' + (data.risk || 'n/a') + ')\n'
  + 'Operator selected: ' + labelName + (overrideFlag ? ' (override)' : ' (matches proposal)') + '\n'
  + 'Callback age at decision: ' + (data.callback_age_seconds != null ? data.callback_age_seconds + 's' : 'unknown') + '\n\n'
  + 'trace_id: ' + (data.trace_id || 'unknown');

const mutation_body_obj = {
  query: 'mutation W7Picker($issueId: String!, $labelIds: [String!]!, $commentBody: String!) { issueUpdate(id: $issueId, input: { labelIds: $labelIds }) { success issue { identifier } } commentCreate(input: { issueId: $issueId, body: $commentBody }) { success comment { id } } }',
  variables: { issueId: data.issue_id, labelIds: nextIds, commentBody }
};

return { json: { ...data, picker_label_name: labelName, picker_display: display, override_flag_picker: overrideFlag, decided_at, next_label_ids: nextIds, mutation_body_obj } };

// w7-picker-error-edit-message (PRO-80 Phase A)
// Reached when w7-picker-build-mutation returns _build_error (e.g., label
// missing from labels_map). Builds a Telegram editMessageText body that
// surfaces the error reason to the operator instead of letting the workflow
// send malformed data to Linear's GraphQL endpoint.
function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const data = $input.item.json;
const errMsg = data._build_error || 'unknown picker error';

const text = '<b>\u26A0 Picker error</b>\n'
  + '<i>' + esc(data.issue_identifier || '?') + '</i>\n'
  + '<code>' + esc(errMsg) + '</code>';

const telegram_error_body = {
  chat_id: data.chat_id,
  message_id: data.message_id,
  text,
  parse_mode: 'HTML',
  reply_markup: { inline_keyboard: [] }
};

return { json: { ...data, telegram_error_body } };

// w7-picker-mark-decided (PRO-80 Phase A)
// Final-stage picker decision: append pending_callbacks 'decided' row (so any
// further taps on the same token are rejected as already_decided) AND append a
// routing_history row with the new picker fields (proposed_worker, selected_worker, override).
const fs = require('fs');
const PENDING = '/miru-data/pending_callbacks.jsonl';
const HISTORY = '/miru-data/routing_history.jsonl';
const WORKFLOW_VERSION = 'phase-2-v1';

const prior = $('w7-picker-build-mutation').item.json;
const editResp = $input.item.json;

const decided_at = prior.decided_at;
const action = prior.action;
const action_label = prior.picker_display;
const token = prior.token;
const trace_id = prior.trace_id;
const task_id = prior.issue_id;
const task_identifier = prior.issue_identifier;
const proposed_worker = prior.chosen_worker;
const selected_worker = prior.picker_label_name;
const override = !!prior.override_flag_picker;

// 1) pending_callbacks.jsonl: 'decided' row, source='picker'
const decidedRow = {
  kind: 'decided',
  token,
  action,
  action_label,
  decided_at,
  decided_by_user_id: prior.from_user_id != null ? prior.from_user_id : null,
  trace_id,
  task_id,
  task_identifier,
  edit_message_ok: !(editResp && editResp.error),
  source: 'picker'
};
fs.appendFileSync(PENDING, JSON.stringify(decidedRow) + '\n');

// 2) routing_history.jsonl: outcome='picker-decided' with PRO-80 fields
const historyRow = {
  timestamp: decided_at,
  trace_id,
  task_id,
  task_identifier,
  extracted_signals: null,
  ranked_candidates: null,
  chosen_worker: proposed_worker,
  confidence: prior.confidence,
  risk: prior.risk,
  operator_override_flag: override,
  outcome: 'picker-decided',
  worker_response_ref: 'callback-picker-' + token,
  proposed_model_version: null,
  actual_model_version: null,
  w2_workflow_version: WORKFLOW_VERSION,
  callback_source: 'telegram',
  button_tapped: action_label,
  button_set: 'picker',
  callback_age_seconds: prior.callback_age_seconds != null ? prior.callback_age_seconds : null,
  decided_at,
  decided_by_user_id: prior.from_user_id != null ? prior.from_user_id : null,
  proposed_worker,
  selected_worker,
  override
};
fs.appendFileSync(HISTORY, JSON.stringify(historyRow) + '\n');

return { json: { ...prior, _decided_persisted: true, _history_persisted: true } };

// w7-mint-original-keyboard (PRO-80 Phase A)
// Back tap: re-mint the original keyboard with fresh HMACs. Re-uses the same
// token; new nonces and ts_hex. Restores 2-button layout for watchdog-originated
// messages (button_set === 'watchdog'), 4-button layout otherwise.
const crypto = require('crypto');
const ANCHOR_UNIX = 1767225600;

const data = $input.item.json;
const secret = $env.TELEGRAM_CALLBACK_SECRET;
if (!secret) throw new Error('TELEGRAM_CALLBACK_SECRET not set');

const token = data.token;
const ts_minutes = Math.floor((Math.floor(Date.now()/1000) - ANCHOR_UNIX) / 60);
const ts_hex = ts_minutes.toString(16).padStart(8, '0').slice(-8);

function origButton(actionCode, label) {
  const nonce = crypto.randomBytes(4).toString('hex');
  const payload = token + actionCode + nonce + ts_hex;
  const hmac = crypto.createHmac('sha256', secret).update(payload).digest('hex').slice(0, 32);
  const cb = token + actionCode + nonce + ts_hex + hmac;
  if (cb.length !== 61) throw new Error('original-keyboard callback_data length mismatch: ' + cb.length);
  return { text: label, callback_data: cb };
}

const isWatchdog = data.button_set === 'watchdog';
const inline_keyboard = isWatchdog
  ? [[origButton('o', 'Override'), origButton('t', 'Triage')]]
  : [
      [origButton('a', 'Approve'), origButton('o', 'Override')],
      [origButton('t', 'Triage'), origButton('r', 'Request Revision')]
    ];

const telegram_edit_body = {
  chat_id: data.chat_id,
  message_id: data.message_id,
  reply_markup: { inline_keyboard }
};

return { json: { ...data, telegram_edit_body, _back_minted_at: new Date().toISOString() } };

// w7-determine-dispatch-target (PRO-84)
// Reached after w7011-mark-decided (Approve flow) OR w7-picker-mark-decided (Picker flow).
// Extracts the dispatchable worker label name. Returns _no_dispatch=true for non-dispatchable
// actions (Triage, Request Revision, picker Triage). Cursor IS dispatchable (degenerate path
// in W4 produces an Open-in-Linear edit; the button + W4 invocation still happen).
const data = $input.item.json;
const DISPATCHABLE = new Set(['claude-code', 'cursor', 'codex', 'gemini']);

let target = null;
let flow = null;
if (data.action === 'a') {
  // Approve flow: target is the originally chosen worker.
  target = data.chosen_worker || null;
  flow = 'approve';
} else if (data.action === 'c' || data.action === 'u' || data.action === 'x' || data.action === 'g') {
  // Picker flow: target is the operator-selected label.
  target = data.picker_label_name || null;
  flow = 'picker';
}
// Triage ('t', 'T'), Request Revision ('r'), Back ('b'), unknown -> no dispatch target.

if (!target || !DISPATCHABLE.has(target)) {
  return { json: { ...data, _no_dispatch: true, _no_dispatch_reason: target ? ('non-dispatchable target: ' + target) : 'no target (action=' + data.action + ')' } };
}

return { json: { ...data, _no_dispatch: false, dispatch_target_worker: target, dispatch_flow: flow } };

// w7-build-dispatch-message (PRO-84)
// Builds the second-stage Telegram sendMessage payload with a 'Dispatch' inline button.
// Mints a NEW callback_data for action='d' using the SAME token (so W4's pending_callbacks
// lookup can correlate). HMAC anchor + algorithm match w7004 / w7-mint-picker-keyboard.
// Per-worker button label: claude-code/codex/gemini get '🚀 Dispatch <worker>',
// cursor gets '🔗 Open in Linear (Cursor)' (degenerate path handled in W4).
const crypto = require('crypto');
const ANCHOR_UNIX = 1767225600;

const data = $input.item.json;
const secret = $env.TELEGRAM_CALLBACK_SECRET;
if (!secret) throw new Error('TELEGRAM_CALLBACK_SECRET not set');

const token = data.token;
const worker = data.dispatch_target_worker;

const LABEL_MAP = {
  'claude-code': '\uD83D\uDE80 Dispatch Claude Code',
  'codex': '\uD83D\uDE80 Dispatch Codex',
  'gemini': '\uD83D\uDE80 Dispatch Gemini CLI',
  'cursor': '\uD83D\uDD17 Open in Linear (Cursor)'
};
const buttonText = LABEL_MAP[worker];
if (!buttonText) throw new Error('no button label mapping for worker: ' + worker);

const nonce = crypto.randomBytes(4).toString('hex');
const ts_minutes = Math.floor((Math.floor(Date.now()/1000) - ANCHOR_UNIX) / 60);
const ts_hex = ts_minutes.toString(16).padStart(8, '0').slice(-8);
const payload = token + 'd' + nonce + ts_hex;
const hmac = crypto.createHmac('sha256', secret).update(payload).digest('hex').slice(0, 32);
const callback_data = token + 'd' + nonce + ts_hex + hmac;
if (callback_data.length !== 61) throw new Error('dispatch callback_data length mismatch: ' + callback_data.length);

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const issue_identifier = data.issue_identifier || data.task_identifier || '?';
const text = '<b>\u2705 Approved: ' + esc(worker) + '</b>\n<i>' + esc(issue_identifier) + '</i>';

const telegram_send_body = {
  chat_id: data.chat_id,
  text,
  parse_mode: 'HTML',
  reply_markup: { inline_keyboard: [[{ text: buttonText, callback_data }]] }
};

return { json: { ...data, dispatch_callback_data: callback_data, dispatch_button_text: buttonText, dispatch_minted_at: new Date().toISOString(), telegram_send_body } };

// w7-store-pending-dispatch (PRO-84)
// Append a pending_callbacks row with kind='dispatch' so W4's lookup-by-(token, kind=dispatch)
// can pull worker/issue_id/issue_url/dispatch message context. Append-only per PRO-77.
const fs = require('fs');
const PENDING = '/miru-data/pending_callbacks.jsonl';

const prior = $('w7-build-dispatch-message').item.json;
const sendResp = $input.item.json;

// Telegram sendMessage response shape: { ok: true, result: { message_id, chat: { id }, ... } }
// On HTTP failure (continueOnFail), $json contains the error response shape -- still proceed,
// but dispatch_message_id may be null. The button + message text reach Telegram regardless
// in the happy case; failure is a Telegram API outage which is its own escalation.
let dispatch_message_id = null;
let dispatch_chat_id = prior.chat_id || null;
if (sendResp && sendResp.ok && sendResp.result) {
  dispatch_message_id = sendResp.result.message_id || null;
  if (sendResp.result.chat && sendResp.result.chat.id != null) dispatch_chat_id = sendResp.result.chat.id;
}

const issue_url = prior.issue_url || (prior.issue_identifier ? ('https://linear.app/project-miru/issue/' + prior.issue_identifier) : null);

const row = {
  schema_version: 'v1',
  kind: 'dispatch',
  token: prior.token,
  trace_id: prior.trace_id || prior.token,
  worker: prior.dispatch_target_worker,
  flow: prior.dispatch_flow,
  issue_id: prior.issue_id || prior.task_id || null,
  issue_identifier: prior.issue_identifier || prior.task_identifier || null,
  issue_url,
  dispatch_chat_id,
  dispatch_message_id,
  dispatch_callback_data: prior.dispatch_callback_data,
  prompt_path: 'data/n8n_inbox/' + (prior.trace_id || prior.token) + '.json',
  status: 'awaiting',
  created_at: prior.dispatch_minted_at || new Date().toISOString(),
  send_message_ok: !!(sendResp && sendResp.ok)
};
fs.appendFileSync(PENDING, JSON.stringify(row) + '\n');

return { json: { ...prior, _dispatch_pending_persisted: true, dispatch_message_id, dispatch_chat_id } };
